-- Revisión pedagógica del grado 1.
-- Las 39 evidencias del MEN no cambian. Cambia cómo está escrito cada
-- ejercicio (enunciado corto, opciones cortas, palabras de niño) y el ORDEN
-- dentro de cada lección: de lo concreto a lo abstracto.

-- El orden ya no lo manda el número de evidencia (una clasificación curricular,
-- no una rampa de dificultad) sino la posición dentro de la lección. La columna
-- pasa a llamarse por lo que de verdad significa.
do $$
begin
  if exists (select 1 from information_schema.columns
             where table_name = 'exercises' and column_name = 'order_in_evidence') then
    alter table exercises rename column order_in_evidence to order_in_lesson;
  end if;
end $$;

do $$
declare v_subject uuid;
begin
  select id into v_subject from subjects where slug = 'matematicas';
  delete from exercises where evidence_id in (
    select le.id from learning_evidences le
    join dbas d on d.id = le.dba_id
    where d.subject_id = v_subject and d.grade = 1);
  delete from learning_evidences where dba_id in (
    select id from dbas where subject_id = v_subject and grade = 1);
end $$;

-- ===== DBA 1: 5 evidencias, 10 ejercicios =====

-- ===== DBA 2: 5 evidencias, 12 ejercicios =====

-- ===== DBA 3: 4 evidencias, 10 ejercicios =====

-- ===== DBA 4: 4 evidencias, 9 ejercicios =====

-- ===== DBA 5: 3 evidencias, 8 ejercicios =====

-- ===== DBA 6: 4 evidencias, 9 ejercicios =====

-- ===== DBA 7: 4 evidencias, 7 ejercicios =====

-- ===== DBA 8: 3 evidencias, 7 ejercicios =====

-- ===== DBA 9: 3 evidencias, 8 ejercicios =====

-- ===== DBA 10: 4 evidencias, 8 ejercicios =====

do $$
declare n_ev int; n_ex int; n_malas int; n_largas int;
begin
  select count(*) into n_ev from learning_evidences le join dbas d on d.id = le.dba_id
    join subjects s on s.id = d.subject_id and s.slug = 'matematicas' where d.grade = 1;
  select count(*) into n_ex from exercises e join learning_evidences le on le.id = e.evidence_id
    join dbas d on d.id = le.dba_id join subjects s on s.id = d.subject_id and s.slug = 'matematicas'
    where d.grade = 1;
  select count(*) into n_malas from exercises e join learning_evidences le on le.id = e.evidence_id
    join dbas d on d.id = le.dba_id join subjects s on s.id = d.subject_id and s.slug = 'matematicas'
    where d.grade = 1 and (jsonb_array_length(e.config->'options') <> 4
      or (select count(distinct v) from jsonb_array_elements_text(e.config->'options') v) <> 4);
  -- Un enunciado de más de 70 caracteres ya no lo lee un niño de primero: mide
  -- lectura, no matemáticas. Es la regla que motivó toda esta revisión, así que
  -- se comprueba en vez de confiar en que la respetamos.
  select count(*) into n_largas from exercises e join learning_evidences le on le.id = e.evidence_id
    join dbas d on d.id = le.dba_id join subjects s on s.id = d.subject_id and s.slug = 'matematicas'
    where d.grade = 1 and length(e.prompt) > 70;
  if n_ev <> 39 then raise exception 'evidencias: % (esperadas 39)', n_ev; end if;
  if n_ex <> 88 then raise exception 'ejercicios: % (esperados 88)', n_ex; end if;
  if n_malas <> 0 then raise exception '% ejercicios sin 4 opciones distintas', n_malas; end if;
  if n_largas <> 0 then raise exception '% enunciados de más de 70 caracteres', n_largas; end if;
end $$;
